'use strict';
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const http = require('http');

const TEMPLATE_DIR = path.resolve(__dirname, 'templates');
const ALLOWED_EXTENSIONS = ['.html', '.txt', '.md'];

class TemplateCache {
  constructor() {
    this._cache = new Map();
    this._hits = 0;
    this._misses = 0;
  }

  get(key) {
    if (this._cache.has(key)) {
      this._hits++;
      return this._cache.get(key);
    }
    this._misses++;
    return null;
  }

  set(key, value) {
    this._cache.set(key, value);
  }

  stats() {
    return { hits: this._hits, misses: this._misses, size: this._cache.size };
  }
}

class TemplateEngine {
  constructor(options = {}) {
    this.baseDir = options.baseDir || TEMPLATE_DIR;
    this.cache = new TemplateCache();
    this.maxDepth = options.maxDepth || 3;
    this.enableIncludes = options.enableIncludes !== false;
  }

  _validateExtension(filePath) {
    const ext = path.extname(filePath).toLowerCase();
    return ALLOWED_EXTENSIONS.includes(ext);
  }

  _isWithinBase(resolvedPath) {
    const normalizedBase = path.resolve(this.baseDir) + path.sep;
    const normalizedTarget = path.resolve(resolvedPath);
    // Check that the resolved path starts with the base directory
    return normalizedTarget.startsWith(normalizedBase) ||
           normalizedTarget === path.resolve(this.baseDir);
  }

  _resolvePath(templateName) {
    // Remove any null bytes
    const cleaned = templateName.replace(/\x00/g, '');
    // Resolve relative to base
    const resolved = path.resolve(this.baseDir, cleaned);
    return resolved;
  }

  _processIncludes(content, depth) {
    if (!this.enableIncludes || depth >= this.maxDepth) {
      return content;
    }
    // Process {{include "filename"}} directives
    const includeRegex = /\{\{include\s+"([^"]+)"\s*\}\}/g;
    return content.replace(includeRegex, (match, includePath) => {
      try {
        return this._loadTemplate(includePath, depth + 1);
      } catch (e) {
        return `<!-- include error: ${e.message} -->`;
      }
    });
  }

  _loadTemplate(templateName, depth = 0) {
    const cached = this.cache.get(templateName);
    if (cached !== null) {
      return cached;
    }

    const resolved = this._resolvePath(templateName);

    if (!this._validateExtension(resolved)) {
      throw new Error(`Invalid extension for template: ${templateName}`);
    }

    if (!this._isWithinBase(resolved)) {
      throw new Error(`Template path outside base directory: ${templateName}`);
    }

    const content = fs.readFileSync(resolved, 'utf8');
    const processed = this._processIncludes(content, depth);
    this.cache.set(templateName, processed);
    return processed;
  }

  render(templateName, variables = {}) {
    const content = this._loadTemplate(templateName);
    // Replace {{variable}} with provided values (safe: HTML-escaped)
    return content.replace(/\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\}\}/g, (match, varName) => {
      if (varName in variables) {
        return this._escapeHtml(String(variables[varName]));
      }
      return match;
    });
  }

  _escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }
}

class RequestHandler {
  constructor() {
    this.engine = new TemplateEngine({ baseDir: TEMPLATE_DIR });
    this.rateLimiter = new Map();
  }

  _checkRateLimit(ip) {
    const now = Date.now();
    const windowMs = 60000;
    const maxRequests = 100;

    if (!this.rateLimiter.has(ip)) {
      this.rateLimiter.set(ip, []);
    }

    const requests = this.rateLimiter.get(ip).filter(t => t > now - windowMs);
    this.rateLimiter.set(ip, requests);

    if (requests.length >= maxRequests) {
      return false;
    }

    requests.push(now);
    return true;
  }

  _parseTemplateName(urlPath) {
    // Extract template name from URL path
    // URL: /render/<templateName>
    const match = urlPath.match(/^\/render\/(.+)$/);
    if (!match) return null;

    let templateName = decodeURIComponent(match[1]);

    // Security: only allow simple filenames (alphanumeric, hyphens, underscores, dots, single slash for subdirs)
    if (!/^[a-zA-Z0-9_\-][a-zA-Z0-9_\-.\/]*$/.test(templateName)) {
      return null;
    }

    // Block path traversal sequences
    if (templateName.includes('..') || templateName.includes('//')) {
      return null;
    }

    // Strip leading slashes and dots for relative path safety
    templateName = templateName.replace(/^\.+/g, '');
    templateName = templateName.replace(/^\/+/g, '');

    return templateName;
  }

  handle(req, res) {
    const ip = req.socket.remoteAddress || '127.0.0.1';

    if (!this._checkRateLimit(ip)) {
      res.writeHead(429, { 'Content-Type': 'text/plain' });
      res.end('Rate limit exceeded');
      return;
    }

    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

    if (req.method !== 'GET') {
      res.writeHead(405, { 'Content-Type': 'text/plain' });
      res.end('Method not allowed');
      return;
    }

    if (url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok', cache: this.engine.cache.stats() }));
      return;
    }

    const templateName = this._parseTemplateName(url.pathname);
    if (!templateName) {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('Not found');
      return;
    }

    try {
      const variables = {};
      for (const [key, value] of url.searchParams) {
        if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(key)) {
          variables[key] = value;
        }
      }

      const rendered = this.engine.render(templateName, variables);
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(rendered);
    } catch (e) {
      // Do not leak internal error details (e.g., filesystem paths) to clients.
      console.error('Render error:', e);
      res.writeHead(400, { 'Content-Type': 'text/plain' });
      res.end('Bad request');
    }
  }
}

const handler = new RequestHandler();
const server = http.createServer((req, res) => handler.handle(req, res));
server.listen(3000);

module.exports = { TemplateEngine, RequestHandler, TemplateCache };
